			db.setObject('', { foo: 1, derp: 2 }, (err) => {
				assert.ifError(err);
				done();
			});
		});

		it('should do nothing if data is falsy', (done) => {
			db.setObject('falsy', null, (err) => {
				assert.ifError(err);
