'use strict';
const assert = require('assert');
const Redis = require('ioredis');
const createHash = require('./src/database/redis/hash');
(async () => {
  const client = new Redis(process.env.TEST_REDIS_SOCKET);
  client.batch = client.pipeline.bind(client);
  const db = { client };
  createHash(db);
  try {
    await client.hmset('decimal', { score: '1.5', scientific: '2.5e1', count: '2' });
    db.objectCache.set('decimal', { score: '1.5' });
    assert.strictEqual(await db.incrObjectFieldByBulk([
      ['decimal', { score: 2, scientific: -3, count: -1, newField: 5 }],
      ['created', { age: 5, score: -2 }],
    ]), undefined);
    assert.deepStrictEqual(await client.hgetall('decimal'),
      { score: '3.5', scientific: '22', count: '1', newField: '5' });
    assert.strictEqual(db.objectCache.has('decimal'), false);
    assert.deepStrictEqual(await db.getObject('created'), { age: '5', score: '-2' });
    await client.hmset('bad', { age: '10', label: 'text' });
    db.objectCache.set('bad', { age: '10', label: 'text' });
    await assert.rejects(db.incrObjectFieldByBulk([
      ['bad', { age: 2, label: 1 }], ['created', { age: 1 }],
    ]));
    assert.deepStrictEqual(await client.hgetall('bad'), { age: '10', label: 'text' });
    assert.strictEqual(db.objectCache.has('bad'), true);
    assert.strictEqual(await client.hget('created', 'age'), '6');
    await Promise.all(Array.from({ length: 25 }, () =>
      db.incrObjectFieldByBulk([['shared', { a: 1, b: 2 }]])));
    assert.deepStrictEqual(await client.hgetall('shared'), { a: '25', b: '50' });
    await client.hmset('overflow', { early: '1', late: '9223372036854775807' });
    await assert.rejects(db.incrObjectFieldByBulk([['overflow', { early: 1, late: 1 }]]));
    assert.deepStrictEqual(await client.hgetall('overflow'),
      { early: '1', late: '9223372036854775807' });
    await client.hmset('precision', { early: '2', late: '1e+21' });
    await assert.rejects(db.incrObjectFieldByBulk([['precision', { early: 1, late: 3 }]]));
    assert.deepStrictEqual(await client.hgetall('precision'), { early: '2', late: '1e+21' });
    process.stdout.write('Redis final integration passed\n');
  } finally {
    await client.quit();
  }
})().catch((err) => { process.stderr.write(err.stack + '\n'); process.exitCode = 1; });
NODE`;
